// Control A: register the route BEFORE the first request -> maxParams is set
// before any Context is allocated, so everything works.
func TestZZReproParamsControlFreshPool(t *testing.T) {
	router := New()
	router.GET("/test/:name/:last_name/*wild", func(c *Context) {
		t.Logf("handler: name=%q last_name=%q wild=%q (cap=%d)",
			c.Param("name"), c.Param("last_name"), c.Param("wild"), cap(c.Params))
	})
	t.Logf("before first request: engine.maxParams=%d", router.maxParams)

	w := httptest.NewRecorder()
	router.ServeHTTP(w, httptest.NewRequest("GET", "/test/john/smith/is/super/great", nil))
	t.Logf("status=%d", w.Code)
}

// Control B: same order as the bug, but the stale pooled Context is discarded
// after addRoute (pool.New re-runs allocateContext with the new maxParams).
func TestZZReproParamsControlResetPool(t *testing.T) {
	router := New()
	w := httptest.NewRecorder()
	router.ServeHTTP(w, httptest.NewRequest("GET", "/test/john/smith/is/super/great", nil))
	t.Logf("first request status=%d", w.Code)

	router.GET("/test/:name/:last_name/*wild", func(c *Context) {
		t.Logf("handler: name=%q last_name=%q wild=%q (cap=%d)",
			c.Param("name"), c.Param("last_name"), c.Param("wild"), cap(c.Params))
	})
	t.Logf("after addRoute: engine.maxParams=%d", router.maxParams)

	// drop the stale context(s) sitting in the pool
	router.pool = sync.Pool{New: func() any { return router.allocateContext() }}

	w2 := httptest.NewRecorder()
	router.ServeHTTP(w2, httptest.NewRequest("GET", "/test/john/smith/is/super/great", nil))
	t.Logf("second request status=%d", w2.Code)
}

